mapper.sql:
concat_ws('、',if(t.plan_date is null,'计划完成日期',null),
if(t.deliverable is null or trim(t.deliverable)='','交付物',null),
if(t.workflow_status='ACTIVE' and coalesce(t.result_status,'DOING')<>'UNDONE' and t.actual_finish_time is null,'实际完成时间',null),
if(t.workflow_status='ACTIVE' and coalesce(t.result_status,'DOING')<>'UNDONE' and (t.result_desc is null or trim(t.result_desc)=''),'结果说明',null),
if(t.workflow_status='ACTIVE' and coalesce(t.result_status,'DOING')<>'UNDONE' and not exists(select 1 from lab_task_evidence pe where pe.task_id=t.id and pe.del_flag='0'),'交付证据',null),
if(t.workflow_status='ACTIVE' and coalesce(t.result_status,'DOING')='UNDONE' and (t.fail_reason is null or trim(t.fail_reason)=''),'未完成原因',null),
if(t.workflow_status='ACTIVE' and coalesce(t.result_status,'DOING')='UNDONE' and (t.next_action is null or trim(t.next_action)=''),'下一步行动',null),
if(t.coordination_required='1' and t.coordination_owner_id is null,'协同负责人',null),
if(t.coordination_required='1' and t.coordination_dept_id is null,'协同部门',null),
if(t.coordination_required='1' and (t.coordination_content is null or trim(t.coordination_content)=''),'协同内容',null),
if(t.coordination_required='1' and (t.coordination_support is null or trim(t.coordination_support)=''),'所需支持',null))

mapper.select:
select r.id,r.task_id,r.business_type,r.business_id,r.episode_no,r.recipient_id,r.reminder_type,r.reminder_level,r.reminder_date, r.title,r.reminder_content,r.read_flag,r.read_time,r.send_time,r.idempotency_key,r.version,r.del_flag,r.create_by,r.create_time, r.update_by,r.update_time,r.remark from lab_reminder r join lab_member recipient on recipient.id=r.recipient_id and recipient.del_flag='0' where r.del_flag='0'
and recipient.biz_line=#{scope.bizLine} and r.recipient_id=#{scope.memberId}
and r.read_flag='0' order by r.read_flag,r.reminder_date desc,r.id desc

select i.id,'IPR' item_type,i.ipr_name title,i.ipr_stage item_status,i.planned_submit_date due_date
from lab_ipr i where i.status='ACTIVE' and i.del_flag='0' and i.planned_submit_date between date_sub(date(#{asOf}),interval 30 day) and date_add(date(#{asOf}),interval 90 day)
order by i.planned_submit_date,i.id limit 20
